Subroutine Suspendable Cook(amount As Integer, counter As Channel<Integer>)
  For order <- 1 To amount Do
    Define accepted As Boolean <- Await counter.send(order);
    If Not accepted Then
      Write "The counter closed";
    EndIf
  EndFor
EndSubroutine

Algorithm Orders
  Define amount As Integer;
  Read amount;
  Define counter As Channel<Integer> <- channel(2);
  Tasks
    Spawn Cook(amount, counter);
    Define delivered As Integer <- 0;
    Repeat
      Switch Await counter.receive() Do
        Some(order):
          Write "I hand over order ", order;
          delivered <- delivered + 1;
        None: Break;
      EndSwitch
    Until False
    Write "Delivered: ", delivered;
  EndTasks
EndAlgorithm

